code.java:
public String pangrams(String s) {
    boolean[] seen = new boolean[26];
    int distinct = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = Character.toLowerCase(s.charAt(i));
        if (c >= 'a' && c <= 'z' && !seen[c - 'a']) {
            seen[c - 'a'] = true;
            distinct++;
        }
    }
    return distinct == 26 ? "pangram" : "not pangram";
}

code.python:
def pangrams(self, s: str) -> str:
    seen = [False] * 26
    distinct = 0
    for ch in s.lower():
        if 'a' <= ch <= 'z' and not seen[ord(ch) - ord('a')]:
            seen[ord(ch) - ord('a')] = True
            distinct += 1
    return "pangram" if distinct == 26 else "not pangram"

